<template><main class="page"><header><h1>Settings</h1><nav><RouterLink to="/checkout">Checkout</RouterLink> · <RouterLink to="/items">Items</RouterLink> · <RouterLink to="/borrowers">Borrowers</RouterLink></nav></header><section><h2>Password</h2><button @click="resetPassword">Email me a password reset link</button><p v-if="message">{{ message }}</p></section><section><h2>Device sessions</h2><button @click="load">Refresh</button><ul><li v-for="session in sessions" :key="session.id"><strong>{{ session.device_label||'Unknown device' }}</strong> — last used {{ new Date(session.last_seen_at).toLocaleString() }} <span v-if="session.is_current">(current)</span> <button @click="revoke(session.id)">Revoke</button></li></ul></section></main></template>
<script setup lang="ts">import{onMounted,ref}from"vue";import{RouterLink}from"vue-router";import{getAuthState}from"../../store/authState";import{supabase}from"../../services/supabaseClient";import{listAccountSessions,revokeAccountSession,type AccountSessionItem}from"../../services/adminOpsService";const sessions=ref<AccountSessionItem[]>([]),message=ref("");const load=async()=>{sessions.value=(await listAccountSessions()).sessions};const revoke=async(id:string)=>{await revokeAccountSession(id);await load();};const resetPassword=async()=>{const email=getAuthState().email;if(!email)return;const{error}=await supabase.auth.resetPasswordForEmail(email,{redirectTo:`${location.origin}/reset-password`});message.value=error?"Unable to send reset link.":"Password reset email sent.";};onMounted(()=>void load());</script>
